33: // 2. 어르신 맞춤형 음성합성 (TTS) 재생 로직
34: const speakText = (text) => {
35:   if (!window.speechSynthesis) return;
36:   window.speechSynthesis.cancel(); // 진행중인 음성 중단
37: 
38:   const utterance = new SpeechSynthesisUtterance(text);
39:   utterance.lang = 'ko-KR';
40:   
41:   // 한국어 정격 보이스 탐색 및 지정
42:   const voices = window.speechSynthesis.getVoices();
