46:   utterance.rate = 0.85; // 고령층 인지를 돕기 위한 0.85 배속 감속 재생
47:   utterance.pitch = 1.0;
48:   
49:   utterance.onstart = () => setRobotEmotion('happy'); // 말하는 도중 미소 표정
50:   utterance.onend = () => setRobotEmotion('neutral'); // 종료 후 기본 표정
51: 
52:   window.speechSynthesis.speak(utterance);
53: };
54: ```
